import { Group, Mesh, Vector3, Color, Clock } from 'three/webgpu';
import gsap from 'gsap';
import { TextGeometry } from '@/text';

/**
 * Stat tile for Collection – compact metric card on machined surface.
 * Exports a synchronous function that returns a Three.js Object3D.
 */
export default function createNode(config, ctx) {
  // ---------------------------------------------------------------------------
  // 1. Load the machined gear mesh (GLB) as the card body.
  //    ctx.glbLoader.get() is assumed to return a cached, ready-to-use Object3D.
  // ---------------------------------------------------------------------------
  const glbRoot = ctx.glbLoader.get(config.meshUrl);
  const mesh = glbRoot.clone(); // clone to avoid sharing if reused

  // Wrap in a group to apply transforms and attach handlers.
  const group = new Group();
  group.add(mesh);

  // Apply scene transforms from config.
  const pos = config.scenePosition.position || { x: 0, y: 0, z: 0 };
  const rot = config.scenePosition.rotation || { x: 0, y: 0, z: 0 };
  const scl = config.scenePosition.scale || { x: 1, y: 1, z: 1 };
  group.position.set(pos.x, pos.y, pos.z);
  group.rotation.set(rot.x, rot.y, rot.z);
  group.scale.set(scl.x, scl.y, scl.z);

  // ---------------------------------------------------------------------------
  // 2. Apply all cinematic primitives from config.
  // ---------------------------------------------------------------------------
  if (config.cinematicPrimitives) {
    config.cinematicPrimitives.forEach((prim) => {
      ctx.primitives[prim.name](group, prim.params);
    });
  }

  // ---------------------------------------------------------------------------
  // 3. Event handlers (hover → rise‑in, click → emit).
  // ---------------------------------------------------------------------------
  const hoverTimeline = gsap.timeline({ paused: true });
  hoverTimeline.to(group.position, {
    y: group.position.y + 0.15,
    duration: 0.2,
    ease: 'power3.out',
  });

  group.userData.handlers = {
    onPointerEnter: () => {
      hoverTimeline.play();
    },
    onPointerLeave: () => {
      hoverTimeline.reverse();
    },
    onPointerDown: () => {
      // Click effect: emit navigation event
      // We assume there's a global event system; here we simply call an
      // emit function if available. Otherwise store event for later dispatch.
      if (typeof window.__prismEmit === 'function') {
        window.__prismEmit('hub-collection.select');
      }
    },
  };

  // ---------------------------------------------------------------------------
  // 4. Entrance animation: weighted‑settle (overshoot scale and position).
  // ---------------------------------------------------------------------------
  const entranceTimeline = gsap.timeline();
  entranceTimeline.from(group.scale, {
    x: 0.97,
    y: 0.97,
    z: 0.97,
    duration: 0.9,
    ease: 'back.out(1.7)',
  });
  entranceTimeline.from(
    group.position,
    {
      y: group.position.y + 0.4,
      duration: 0.7,
      ease: 'power3.out',
    },
    0
  );

  // ---------------------------------------------------------------------------
  // 5. Cleanup – kill GSAP timelines, dispose mesh.
  // ---------------------------------------------------------------------------
  group.userData.cleanup = () => {
    entranceTimeline.kill();
    hoverTimeline.kill();
    // Dispose geometry and materials recursively
    group.traverse((child) => {
      if (child.isMesh) {
        child.geometry?.dispose();
        if (Array.isArray(child.material)) {
          child.material.forEach((m) => m.dispose());
        } else {
          child.material?.dispose();
        }
      }
    });
  };

  return group;
}
